21	// External-command resolution, kubectl-style. When the user invokes
22	// `entire <name>` and <name> isn't a built-in subcommand, look for an
23	// `entire-<name>` binary on PATH and exec it with the remaining args.
24	// Stdio and exit codes pass through. Binaries matching the agent
25	// protocol prefix are reserved for the external agent registry and
26	// skipped here.
27	const (
28		pluginBinaryPrefix      = "entire-"
29		agentPluginBinaryPrefix = "entire-agent-"
30	)
