32	// MaybeRunPlugin returns (true, exitCode) when an external command was
33	// resolved and run. On launch failure (e.g. missing executable bit)
34	// returns (true, 1) after printing to stderr. On no-match returns
35	// (false, 0) so the caller can fall through to Cobra.
36	//
37	// Telemetry and the version-check notice mirror Cobra's PersistentPostRun
38	// behavior for built-ins: both fire only on a successful (exit-0) run.
39	func MaybeRunPlugin(ctx context.Context, rootCmd *cobra.Command, args []string) (handled bool, exitCode int) {
40		binPath, pluginArgs, ok := resolvePlugin(rootCmd, args)
41		if !ok {
42			return false, 0
43		}
44		pluginName := args[0]
45		exitCode = runPlugin(ctx, binPath, pluginArgs)
46		if exitCode == 0 {
47			maybeTrackPluginInvocation(ctx, pluginName)
48			versioncheck.CheckAndNotify(ctx, os.Stdout, versioninfo.Version)
49		}
50		return true, exitCode
51	}
