70	func resolvePlugin(rootCmd *cobra.Command, args []string) (binPath string, pluginArgs []string, ok bool) {
71		if len(args) == 0 {
72			return "", nil, false
73		}
74		name := args[0]
75		if !isPluginCandidate(name) {
76			return "", nil, false
77		}
78		// Built-in commands always win.
79		if cmd, _, err := rootCmd.Find(args); err == nil && cmd != rootCmd {
80			return "", nil, false
81		}
82		binName := pluginBinaryPrefix + name
83		binPath, err := exec.LookPath(binName)
84		if err != nil {
85			// LookPath conflates "not on PATH" with "found but not executable".
86			// Distinguish: if a file with this name exists on PATH but isn't
87			// executable, surface that as a launch error rather than falling
88			// through to Cobra's generic unknown-command path.
89			if p, found := findInaccessiblePlugin(binName); found {
90				return p, args[1:], true
91			}
92			return "", nil, false
93		}
94		if isAgentProtocolBinary(binPath) {
95			return "", nil, false
96		}
97		return binPath, args[1:], true
98	}
