100	// findInaccessiblePlugin scans PATH for a non-directory file with the
101	// given name. Only meaningful after exec.LookPath has already failed —
102	// indicates the file exists but lacks the executable bit (or the
103	// equivalent platform-specific accessibility).
104	func findInaccessiblePlugin(filename string) (string, bool) {
105		for _, dir := range filepath.SplitList(os.Getenv("PATH")) {
106			if dir == "" {
107				continue
108			}
109			candidate := filepath.Join(dir, filename)
110			info, err := os.Stat(candidate) //nolint:gosec // PATH entries are user-trusted; scanning them is the point.
111			if err != nil || info.IsDir() {
112				continue
113			}
114			return candidate, true
115		}
116		return "", false
117	}
