119	func isPluginCandidate(name string) bool {
120		if name == "" {
121			return false
122		}
123		if strings.HasPrefix(name, "-") {
124			return false
125		}
126		// `agent-*` is reserved for the external agent protocol.
127		if strings.HasPrefix(name, "agent-") {
128			return false
129		}
130		if strings.ContainsAny(name, `/\`) {
131			return false
132		}
133		return true
134	}
